import {cabinet,rect,circle,text,ring,line,colors,rand,pick,clamp} from './cabinet.js';
export function segmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1),0,1);return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);}
export function createSlice(mount,api){const q=cabinet(mount,api,{accent:'#ff8eac'}),c=q.c;let objects=[],trail=[],spawn=.4,life=3,last=null,chain=0,chainTime=0,cursor={x:180,y:240},serial=0;
 function cut(a,b){if(!q.active)return;for(const o of objects){if(o.cut||segmentDistance(o,a,b)>o.r+4)continue;o.cut=true;if(o.bomb){life--;chain=0;q.sound('bomb');q.burst(o.x,o.y,'#ff8eac',20);q.say('AVOID THE × PRISMS');if(!life){q.finish('A sharp finish.',`${q.score} points. Slice the gems, spare the hazards.`);return;}}else{chain=chainTime>0?chain+1:1;chainTime=.22;const pts=10*Math.min(5,chain);q.add(pts);q.sound('slice',Math.min(chain*2,10));q.burst(o.x,o.y,o.color,18);if(chain>1)q.say(`${chain} GEM COMBO · +${pts}`);}}trail.push({a:{...a},b:{...b},t:.25});trail=trail.slice(-30);}
 return {start(){objects=[];trail=[];spawn=.4;life=3;last=null;chain=0;chainTime=0;serial=0;cursor={x:180,y:240};q.start();},pointerDown(p){last=q.local(p);cut(last,last);},pointerMove(p){if(last){const n=q.local(p);cut(last,n);last=n;}},pointerUp(p){if(last)cut(last,q.local(p));last=null;},cancel(){last=null;},direction(d){const old={...cursor};cursor.x=clamp(cursor.x+(d==='left'?-28:d==='right'?28:0),20,340);cursor.y=clamp(cursor.y+(d==='up'?-28:d==='down'?28:0),45,430);cut(old,cursor);},action(){cut({x:cursor.x-38,y:cursor.y+25},{x:cursor.x+38,y:cursor.y-25});},tick(dt){q.frame(dt,dt=>{spawn-=dt;chainTime-=dt;if(spawn<=0){const n=2+(q.elapsed>15?1:0);for(let i=0;i<n;i++){serial++;objects.push({x:rand(65,295),y:460+i*20,vx:rand(-55,55),vy:rand(-410,-360),r:22,color:pick(colors),angle:rand(0,6),spin:rand(-2,2),bomb:serial>7&&serial%7===0,cut:false});}spawn=Math.max(.9,1.4-q.elapsed*.007);}for(const o of objects){o.vy+=300*dt;o.x+=o.vx*dt;o.y+=o.vy*dt;o.angle+=o.spin*dt;if(o.x<24||o.x>336){o.x=clamp(o.x,24,336);o.vx*=-1;}if(o.y>500&&o.vy>0&&!o.cut){o.cut=true;if(!o.bomb){life--;q.sound('miss');q.say('ONE GEM GOT AWAY');if(life<=0){q.finish('The last slice.',`${q.score} points. Catch the gems near the top of their arc.`);return;}}}}objects=objects.filter(o=>!o.cut&&o.y<510);trail=trail.filter(t=>(t.t-=dt)>0);if(q.elapsed>=45)q.finish('A cut above.',`45 seconds. ${q.score} points.`,true);},()=>{q.header(`${'♥ '.repeat(Math.max(0,life)).trim()}`,`${Math.max(0,Math.ceil(45-q.elapsed))}s`);for(let y=75;y<430;y+=50)line(c,20,y,340,y,'#aebee80a',1);for(const o of objects){c.save();c.translate(o.x,o.y);c.rotate(o.angle);if(o.bomb){rect(c,-22,-22,44,44,'#513040',9);ring(c,0,0,26,'#ff8eac',2);line(c,-8,-8,8,8,'#ff9db8',3);line(c,-8,8,8,-8,'#ff9db8',3);}else{c.beginPath();c.moveTo(0,-26);c.lineTo(24,0);c.lineTo(0,26);c.lineTo(-24,0);c.closePath();c.fillStyle=o.color;c.fill();line(c,0,-24,0,24,'#ffffff66');line(c,-23,0,23,0,'#ffffff66');}c.restore();}for(const t of trail){line(c,t.a.x,t.a.y,t.b.x,t.b.y,`rgba(255,220,238,${t.t*3})`,6);line(c,t.a.x,t.a.y,t.b.x,t.b.y,'#fff4fc',2);}ring(c,cursor.x,cursor.y,9,'#ffffff33',1);q.footer('Swipe through gems. Avoid the ×.');});},destroy:q.destroy};}
